mapper.select:
SELECT *
FROM hr_attendance_record
WHERE id = #{id}
  AND tenant_id = #{tenantId}
LIMIT 1

mapper.update:
UPDATE hr_attendance_record
SET check_in       = COALESCE(#{checkIn}, check_in),
    check_out      = COALESCE(#{checkOut}, check_out),
    exception_type = NULL,
    remark         = CONCAT(IFNULL(remark, ''), #{remarkSuffix}),
    update_by      = #{updateBy}
WHERE id        = #{id}
  AND tenant_id = #{tenantId}
